INSERT OR IGNORE INTO cms_posts(id,path,kind,title,country,sports,draft,published,state,imported,updated_at,updated_by) VALUES ('f594dc02fa3c697e54ff8225','/blog/vodnyy-start-nekotorye-osobennosti.php','blog','Водный старт, некоторые особенности','dahab','["windsurf"]','{"kind":"blog","slug":"vodnyy-start-nekotorye-osobennosti","title":"Водный старт, некоторые особенности","description":"Водный старт: ключевые моменты техники, которые помогают увереннее поднимать парус и выходить на доску.","country":"dahab","sports":["windsurf"],"lang":"ru","date":"2026-04-22","cover":"/assets/img/blog/legacy/vodnyy-start-nekotorye-osobennosti-00.jpg","coverAlt":"Водный старт, некоторые особенности","blocks":[{"type":"text","text":"Очередной отличный день в Дахабе. С утра пораньше гости Ветратории спешат кататься. Бодрящий свежий ветер уже дует и гипнотически манит на воду. Адепты, познавшие эйфорию скорости, смело выкатывают в Спиди-зону, где глубина и пространство позволяют гонять по полной. Но локация требует навыков, помимо умения выводить доску на глиссер. Умение развернуться и, в случае падения, как-то стартовать — среди них. Сегодня коснусь темы старта, водного старта, ибо на глубине нет опоры на грунт, и на доске когда дует и колбасит «за верёвочку» особо не подёргаешь. Можно сказать, что водный старт — один из базовых элементов в виндсёрфинге — это не только полезный навык, но и первоочередной для вашей безопасности на воде. Конкретно, речь пойдёт не о нём самом, а о паре его ключевых моментов, которые могут игнорироваться большинством, даже теми, кто этот навык кое-как освоил, но (моё любимое выражение) не постиг полностью его Дзен!","id":"9cb1f4a71c3acbd62dd4ce39"},{"type":"image","url":"/assets/img/blog/legacy/vodnyy-start-nekotorye-osobennosti-01.jpg","alt":"Водный старт, некоторые особенности","id":"bbac3a45dc781f7f0edf51ff"},{"type":"text","text":"Что ж, поехали. Водный старт — производная бич старта. Это когда райдер, стоя в воде на отмели, лихо манипулируя парусом, заскакивает на доску без использования стартшкотика. Сам ветер помогает ему в этом. Р-р-раз и полетел! Магия? Нисколечко… Мастерство и умение! Дальше человек задумывается: «Нельзя ли такой же трюк провернуть с глубины?» Ответ — да, можно, но требуется как-то поднять прилипший к воде парус. Всей техники тут представлено не будет. Как говорится, многАбукв.  А вот один ключевой секретик я раскрою. Он полезен всем, кто не умеет или умеет, но испытывает проблемы на этапе отклеивания паруса от воды. Не пробуйте это делать за гик, т. е. в центре паруса. Для этих целей используйте топ паруса (верхний кончик). Самая лёгкая его часть — верхушка. Стоит отлепить верхушку, как между ней и основанием, прикреплённым к шарниру на доске образуется мостик, под который сразу начинает поддувать ветер, помогая уже всему полотну отлипнуть от воды.","id":"b75c7f71c63524b3d95f3c94"},{"type":"gallery","images":[{"url":"/assets/img/blog/legacy/vodnyy-start-nekotorye-osobennosti-02.jpg","alt":"Водный старт, некоторые особенности"},{"url":"/assets/img/blog/legacy/vodnyy-start-nekotorye-osobennosti-03.jpg","alt":"Водный старт, некоторые особенности"},{"url":"/assets/img/blog/legacy/vodnyy-start-nekotorye-osobennosti-04.jpg","alt":"Водный старт, некоторые особенности"}],"variant":"grid","id":"42a473bb819506e9af90eb4d"},{"type":"gallery","images":[{"url":"/assets/img/blog/legacy/vodnyy-start-nekotorye-osobennosti-05.jpg","alt":"Водный старт, некоторые особенности"},{"url":"/assets/img/blog/legacy/vodnyy-start-nekotorye-osobennosti-06.jpg","alt":"Водный старт, некоторые особенности"},{"url":"/assets/img/blog/legacy/vodnyy-start-nekotorye-osobennosti-07.jpg","alt":"Водный старт, некоторые особенности"}],"variant":"grid","id":"937de13fcc7bd02a53af7b8e"},{"type":"text","text":"Второй полезный совет касается момента, когда парус уже поднялся, вы перехватились за гик и повисли на ветровой тяге. Если новичку не совсем понятно о чём я — гляньте на фото. Боюсь, мало кто в этой позиции понимает всю механику процесса. Но в целом, ваша задача на данном этапе (внимание!!!) не упираться ногами в борт, а зацепить пяткой задней ноги палубу в точке на оси доски и на СЕРЕДИНКЕ МЕЖДУ ШАРНИРОМ И КОРМОЙ. Запомните: именно положить ногу, а не упереться. И только одну заднюю. Её задача в момент старта (когда вы начинаете добавлять тяги) подтягивать вашу тушку ближе к борту, а не отжимать. Особенно полезно для тех, у кого при старте доска вечно крутится носом на ветер и парус, теряя тягу, топит вас. Ну и, в общем, я лично никогда не учу выполнять водный старт с упором двумя ногами, считаю это дурным тоном и полным непрофессионализмом. Так некоторые инструктора-халтурщики облегчают себе задачу, станции берегут матчасть, но никак не помогают ученикам качественно выполнять водный старт быстро и на любом ветру. Запомните: выполнение с одной ногой — высший пилотаж. Однако, данный способ требует знания ключевых тонких моментов и идеально натренированного чувства баланса.","id":"4687a2be55fa94a7ccc2fb89"},{"type":"gallery","images":[{"url":"/assets/img/blog/legacy/vodnyy-start-nekotorye-osobennosti-08.jpg","alt":"Водный старт, некоторые особенности"},{"url":"/assets/img/blog/legacy/vodnyy-start-nekotorye-osobennosti-09.jpg","alt":"Водный старт, некоторые особенности"},{"url":"/assets/img/blog/legacy/vodnyy-start-nekotorye-osobennosti-10.jpg","alt":"Водный старт, некоторые особенности"}],"variant":"grid","id":"b61c57891c30956feb8ac3fd"},{"type":"text","text":"Итак, две подсказки для водного старта на сегодня: отрывать парус от воды лучше начинать с топа (крайней верхней части), и не упираться ногами в борт, подтягивать задней, положив её на палубу. Надеюсь, те кто сейчас читает это, будучи уже в Дахабе, на Ветратории, тут же смогут проверить, а те, кто лишь собираются к нам — запомнят и попробуют при первом удобном случае. О других тонкостях водного старта поговорим как-нибудь ещё, хотя самые нетерпеливые могут задать вопросы лично и даже попробовать взять урок. Главное — это наличие огромного желания, и непременное стремление совершенствовать свой навык, дабы кататься долго и счастливо.","id":"392ef9b46c6e1f898bb3e45f"},{"type":"gallery","images":[{"url":"/assets/img/blog/legacy/vodnyy-start-nekotorye-osobennosti-11.jpg","alt":"Водный старт, некоторые особенности"},{"url":"/assets/img/blog/legacy/vodnyy-start-nekotorye-osobennosti-12.jpg","alt":"Водный старт, некоторые особенности"},{"url":"/assets/img/blog/legacy/vodnyy-start-nekotorye-osobennosti-13.jpg","alt":"Водный старт, некоторые особенности"}],"variant":"grid","id":"908ab87a52e2dfc93aa9ac7a"},{"type":"text","text":"По ключикам для водного старта провёл вас я, Серёга (a.k.a. PaparazzO)   22.04.2026","id":"319e4f13bd581f3714d9497a"},{"type":"text","text":"Автор: По ключикам для водного старта провёл вас я, Серёга (a.k.a. PaparazzO)","id":"62b57c7c9e9ef69a9368ff6f"}]}','{"kind":"blog","slug":"vodnyy-start-nekotorye-osobennosti","title":"Водный старт, некоторые особенности","description":"Водный старт: ключевые моменты техники, которые помогают увереннее поднимать парус и выходить на доску.","country":"dahab","sports":["windsurf"],"lang":"ru","date":"2026-04-22","cover":"/assets/img/blog/legacy/vodnyy-start-nekotorye-osobennosti-00.jpg","coverAlt":"Водный старт, некоторые особенности","blocks":[{"type":"text","text":"Очередной отличный день в Дахабе. С утра пораньше гости Ветратории спешат кататься. Бодрящий свежий ветер уже дует и гипнотически манит на воду. Адепты, познавшие эйфорию скорости, смело выкатывают в Спиди-зону, где глубина и пространство позволяют гонять по полной. Но локация требует навыков, помимо умения выводить доску на глиссер. Умение развернуться и, в случае падения, как-то стартовать — среди них. Сегодня коснусь темы старта, водного старта, ибо на глубине нет опоры на грунт, и на доске когда дует и колбасит «за верёвочку» особо не подёргаешь. Можно сказать, что водный старт — один из базовых элементов в виндсёрфинге — это не только полезный навык, но и первоочередной для в